data.pageSchema:
{
  "renderer": "page",
  "body": [
    {
      "renderer": "form",
      "controls": [
        {
          "renderer": "input",
          "name": "name",
          "placeholder": "权限名",
          "type": "text",
          "rules": []
        },
        {
          "renderer": "input",
          "name": "description",
          "placeholder": "描述",
          "type": "text",
          "rules": []
        },
        {
          "renderer": "action",
          "text": "搜索",
          "actionType": "submit",
          "body": {}
        }
      ],
      "submitType": "target",
      "inline": true,
      "target": "PermissionTable"
    },
    {
      "renderer": "table",
      "name": "PermissionTable",
      "maxHeight": 570,
      "showExport": true,
      "initApi": {
        "url": "/api/permissions",
        "method": "get",
        "params": {
          "name": "${name}",
          "description": "${description}"
        }
      },
      "initData": {
        "username": ""
      },
      "columns": [
        {
          "name": "id",
          "label": "ID",
          "visibleOn": "",
          "body": []
        },
        {
          "name": "name",
          "label": "名称",
          "visibleOn": "",
          "body": []
        },
        {
          "name": "description",
          "label": "描述",
          "body": []
        },
        {
          "name": "createdBy",
          "label": "创建人",
          "body": []
        },
        {
          "name": "createdAt",
          "label": "创建时间",
          "body": []
        }
      ],
      "actions": [
        {
          "renderer": "action",
          "text": "添加权限",
          "size": "small",
          "actionType": "dialog",
          "body": {
            "body": [
              {
                "renderer": "form",
                "controls": [
                  {
                    "renderer": "input",
                    "name": "name",
                    "label": "名称",
                    "requiredOn": "1",
                    "placeholder": "请输入",
                    "type": "text",
                    "rules": []
                  },
                  {
                    "renderer": "input",
                    "name": "description",
                    "label": "描述",
                    "requiredOn": "1",
                    "placeholder": "请输入",
                    "type": "text",
                    "rules": []
                  }
                ],
                "name": "CreateForm",
                "actionApi": {
                  "url": "/api/permission",
                  "method": "post",
                  "params": {
                    "*": "*"
                  }
                },
                "reload": "PermissionTable"
              }
            ],
            "footer": [
              {
                "renderer": "action",
                "text": "提交",
                "actionType": "trigger",
                "triggered": "CreateForm",
                "body": {}
              }
            ]
          },
          "plain": true,
          "icon": "Plus"
        }
      ],
      "height": 490,
      "showDynamicColumn": true
    }
  ],
  "mergeUrlQuery": true
}
